/**
 * Captain SDK — the only way a Captain app talks to the outside world.
 *
 * Inside the Captain desktop app, `window.captain` is injected by the Space and
 * backs everything with on-device storage (SQLite) and the user's signed-in
 * Captain account. In Captain's web preview, Captain injects a `window.captain`
 * that relays to the Captain page embedding the app. Outside Captain (e.g. a
 * local dev server) a fallback stores data in localStorage.
 *
 * Do not edit this file in generated apps; import from it.
 */
import { useCallback, useEffect, useState } from "react";

export interface CaptainRecord {
  id: string;
  createdAt: string;
  updatedAt: string;
  [field: string]: unknown;
}

export type ConnectorName = "slack" | "google";

export interface CaptainBridge {
  app: { id: string; name: string; version: number };
  db: {
    list(collection: string): Promise<CaptainRecord[]>;
    put(collection: string, record: Partial<CaptainRecord>): Promise<CaptainRecord>;
    remove(collection: string, id: string): Promise<void>;
  };
  ai: {
    /** `maxTokens` caps the answer's length: 4,000 tokens unless set, up to 16,000. */
    generate(request: { prompt: string; system?: string; json?: boolean; maxTokens?: number }): Promise<{ text: string; object?: unknown }>;
  };
  connectors: {
    call(connector: ConnectorName, action: string, input?: Record<string, unknown>): Promise<unknown>;
  };
  /** Fires when data changes outside this window (e.g. the app's bot edited records). */
  onDataChanged?(listener: (collection: string) => void): () => void;
}

declare global {
  interface Window {
    captain?: CaptainBridge;
  }
}

function webFallback(): CaptainBridge {
  const appId = location.pathname.match(/\/a\/([^/]+)/)?.[1] ?? "dev";
  const key = (collection: string) => `captain:${appId}:${collection}`;
  const read = (collection: string): CaptainRecord[] => JSON.parse(localStorage.getItem(key(collection)) ?? "[]");
  const write = (collection: string, records: CaptainRecord[]) =>
    localStorage.setItem(key(collection), JSON.stringify(records));
  const api = async (path: string, body: unknown, confirmed = false): Promise<any> => {
    const response = await fetch(`/api/runtime/${path}`, {
      method: "POST",
      headers: { "content-type": "application/json", ...(confirmed ? { "x-captain-confirmed": "1" } : {}) },
      body: JSON.stringify({ appId, ...(body as object) }),
    });
    const json = await response.json().catch(() => ({ error: response.statusText }));
    if (response.status === 409 && json.needsConfirmation) {
      if (!window.confirm(`${json.summary}\n\n${JSON.stringify(json.details, null, 2)}`)) {
        throw new Error("Cancelled by user");
      }
      return api(path, body, true);
    }
    if (!response.ok) throw new Error(json.error ?? `Request failed (${response.status})`);
    return json;
  };
  return {
    app: { id: appId, name: document.title, version: 0 },
    db: {
      async list(collection) {
        return read(collection);
      },
      async put(collection, record) {
        const records = read(collection);
        const now = new Date().toISOString();
        const existing = records.find((r) => r.id === record.id);
        const next = { ...existing, ...record, id: record.id ?? crypto.randomUUID(), createdAt: existing?.createdAt ?? now, updatedAt: now } as CaptainRecord;
        write(collection, existing ? records.map((r) => (r.id === next.id ? next : r)) : [...records, next]);
        return next;
      },
      async remove(collection, id) {
        write(collection, read(collection).filter((r) => r.id !== id));
      },
    },
    ai: { generate: (request) => api("ai", request) },
    connectors: { call: (connector, action, input = {}) => api("connectors", { connector, action, input }).then((r) => r.result) },
  };
}

export const captain: CaptainBridge = typeof window !== "undefined" && window.captain ? window.captain : webFallback();

/** Ask the AI. With `json: true`, `object` holds the parsed JSON answer. */
export async function ask(prompt: string, options: { system?: string } = {}) {
  return (await captain.ai.generate({ prompt, ...options })).text;
}

export async function askJson<T>(prompt: string, options: { system?: string } = {}): Promise<T> {
  const result = await captain.ai.generate({ prompt, ...options, json: true });
  return result.object as T;
}

/** Typed helpers over `captain.connectors.call`. Write actions ask the user to confirm. */
export const slack = {
  searchMessages: (input: { query: string; count?: number }) =>
    captain.connectors.call("slack", "searchMessages", input) as Promise<{
      total: number;
      messages: { ts: string; date: string; user?: string; text: string; channel?: string; channelId?: string; permalink?: string }[];
    }>,
  listChannels: () =>
    captain.connectors.call("slack", "listChannels") as Promise<{ id: string; name: string; private: boolean; topic?: string }[]>,
  channelHistory: (input: { channel: string; limit?: number; oldest?: string }) =>
    captain.connectors.call("slack", "channelHistory", input) as Promise<{ ts: string; date: string; user?: string; text: string }[]>,
  postMessage: (input: { channel: string; text: string; threadTs?: string }) =>
    captain.connectors.call("slack", "postMessage", input) as Promise<{ ts: string; channel: string }>,
};

export const gmail = {
  searchEmail: (input: { query: string; maxResults?: number }) =>
    captain.connectors.call("google", "searchEmail", input) as Promise<
      { id: string; threadId: string; from?: string; subject?: string; date?: string; snippet: string; unread: boolean }[]
    >,
  readThread: (input: { threadId: string }) =>
    captain.connectors.call("google", "readThread", input) as Promise<
      { id: string; from?: string; to?: string; subject?: string; date?: string; body: string }[]
    >,
  createDraft: (input: { to: string; subject: string; body: string; threadId?: string }) =>
    captain.connectors.call("google", "createDraft", input) as Promise<{ draftId: string }>,
};

/** React hook: live records of one local collection, plus mutators. */
export function useCollection<T extends Record<string, unknown>>(collection: string) {
  const [records, setRecords] = useState<(CaptainRecord & T)[]>([]);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    setRecords((await captain.db.list(collection)) as (CaptainRecord & T)[]);
    setLoading(false);
  }, [collection]);

  useEffect(() => {
    void refresh();
    return captain.onDataChanged?.((changed) => {
      if (changed === collection) void refresh();
    });
  }, [collection, refresh]);

  const put = useCallback(
    async (record: Partial<CaptainRecord> & Partial<T>) => {
      const saved = await captain.db.put(collection, record);
      await refresh();
      return saved as CaptainRecord & T;
    },
    [collection, refresh],
  );

  const remove = useCallback(
    async (id: string) => {
      await captain.db.remove(collection, id);
      await refresh();
    },
    [collection, refresh],
  );

  return { records, loading, put, remove, refresh };
}
